@Component
class DbHealthIndicator implements HealthIndicator {
    private final DataSource ds;
    DbHealthIndicator(DataSource ds) { this.ds = ds; }
    @Override public Health health() {
        try (var c = ds.getConnection()) {          // cheap, bounded check
            return Health.up().withDetail("db", "reachable").build();
        } catch (SQLException e) {
            return Health.down().withDetail("db", "unreachable").build();
        }
    }
}
# probes on the main port: management.endpoint.health.probes.add-additional-paths=true -> /livez, /readyz
# readiness group:          management.endpoint.health.group.readiness.include=readinessState,db

